package cn.dreamingfish.updater.player.launcher.web;
import cn.dreamingfish.launcher.downloads.*;
import cn.dreamingfish.launcher.instances.FileInstanceCatalog;
import cn.dreamingfish.launcher.vanilla.*;
import cn.dreamingfish.launcher.loaders.fabric.FabricPlanner;
import cn.dreamingfish.launcher.loaders.*;
import cn.dreamingfish.launcher.GameInstance.LoaderKind;
import java.io.*;
import java.time.*;
import java.util.*;
public final class InstallationRoutes implements LauncherRoutes,AutoCloseable {
 private final VanillaPlanner planner;private final VanillaInstaller installer;private final TaskManager tasks;private final FileInstanceCatalog instances;private final Clock clock;
 private final FabricPlanner fabric;private final Map<LoaderKind,LoaderProvider> loaders;
 private final InstallationQueries queries;
 private record Preview(String instanceId,VanillaPlan plan,FabricPlanner.Plan fabricPlan,LoaderPlan loaderPlan,Instant expiresAt){}
 private final Map<UUID,Preview> previews=new LinkedHashMap<>();
 public InstallationRoutes(VanillaPlanner planner,VanillaInstaller installer,TaskManager tasks,FileInstanceCatalog instances,Clock clock){this(planner,installer,tasks,instances,clock,null);}
 public InstallationRoutes(VanillaPlanner planner,VanillaInstaller installer,TaskManager tasks,FileInstanceCatalog instances,Clock clock,FabricPlanner fabric){this(planner,installer,tasks,instances,clock,fabric,Duration.ofSeconds(30));}
 public InstallationRoutes(VanillaPlanner planner,VanillaInstaller installer,TaskManager tasks,FileInstanceCatalog instances,Clock clock,FabricPlanner fabric,Map<LoaderKind,LoaderProvider> loaders){this(planner,installer,tasks,instances,clock,fabric,loaders,Duration.ofSeconds(30));}
 InstallationRoutes(VanillaPlanner planner,VanillaInstaller installer,TaskManager tasks,FileInstanceCatalog instances,Clock clock,FabricPlanner fabric,Duration budget){this(planner,installer,tasks,instances,clock,fabric,Map.of(),budget);}
 private InstallationRoutes(VanillaPlanner planner,VanillaInstaller installer,TaskManager tasks,FileInstanceCatalog instances,Clock clock,FabricPlanner fabric,Map<LoaderKind,LoaderProvider> loaders,Duration budget){this.planner=planner;this.installer=installer;this.tasks=tasks;this.instances=instances;this.clock=clock;this.fabric=fabric;this.loaders=Map.copyOf(loaders);this.queries=new InstallationQueries(budget);}
 private String version(String instanceId)throws IOException{try{TaskRequest.uuid(instanceId);}catch(IllegalArgumentException invalid){throw ApiRequest.invalid("实例 ID 无效");}return instances.listing().instances().stream().filter(i->i.instance().id().equals(instanceId)).map(i->i.instance().gameVersion()).findFirst().orElseThrow(()->new LauncherApiException(404,"UNKNOWN_INSTANCE","实例不存在或记录损坏"));}
 @Override public Optional<ApiResponse> handle(ApiRequest r)throws IOException{
  if(!Set.of("/installations/plan","/installations","/installations/verify","/installations/fabric/versions","/installations/loader/versions","/installations/cancel-query").contains(r.path()))return Optional.empty();
  try{
   if(r.path().equals("/installations/cancel-query")){r.requireMethod("POST");r.onlyQuery();r.onlyFields(Set.of("requestId"));queries.cancel(InstallationQueries.id(r.text("requestId",36)));return Optional.of(new ApiResponse(200,Map.of("cancelRequested",true)));}
   if(r.path().equals("/installations/loader/versions")){r.requireMethod("GET");r.onlyQuery("instanceId","loader","requestId");String game=version(r.query().get("instanceId"));var provider=provider(r.query().get("loader"));return queries.run(InstallationQueries.id(r.query().get("requestId")),token->Optional.of(new ApiResponse(200,Map.of("versions",provider.versions(game,token)))));}
   if(r.path().equals("/installations/fabric/versions")){r.requireMethod("GET");r.onlyQuery("instanceId","requestId");String instanceId=r.query().get("instanceId");if(instanceId==null)throw ApiRequest.invalid("需要实例ID");String game=version(instanceId);if(fabric==null)throw new LauncherApiException(503,"SOURCE_UNAVAILABLE","此模式尚未接入Fabric官方目录");return queries.run(InstallationQueries.id(r.query().get("requestId")),token->Optional.of(new ApiResponse(200,Map.of("versions",fabric.versions(game,token)))));}
   if(r.path().equals("/installations")&&r.method().equals("GET")){r.onlyQuery("instanceId");String id=r.query().get("instanceId");if(id==null)throw ApiRequest.invalid("需要实例 ID");version(id);var listing=installer.listing(id);return Optional.of(new ApiResponse(200,Map.of("installations",listing.installations().stream().map(InstallationRoutes::view).toList(),"problems",listing.problems())));}
   r.requireMethod("POST");if(r.path().equals("/installations/plan"))r.onlyQuery("requestId");else r.onlyQuery();
   if(r.path().equals("/installations/plan")){return queries.run(InstallationQueries.id(r.query().get("requestId")),token->{r.onlyFields(Set.of("instanceId","loader","loaderVersion"));String id=r.text("instanceId",36),version=version(id);FabricPlanner.Plan fabricPlan=null;LoaderPlan loaderPlan=null;boolean selected=r.body().has("loader");if(selected){if(!"FABRIC".equals(r.text("loader",16))){loaderPlan=provider(r.text("loader",16)).plan(version,r.text("loaderVersion",128),token);}else{if(fabric==null)throw new LauncherApiException(503,"SOURCE_UNAVAILABLE","此模式尚未接入Fabric");fabricPlan=fabric.plan(version,r.text("loaderVersion",128),token);}}else if(r.body().has("loaderVersion"))throw ApiRequest.invalid("缺少加载器类型");var plan=loaderPlan!=null?loaderPlan.installation():fabricPlan==null?planner.plan(version,token):fabricPlan.installation();UUID key=UUID.randomUUID();Instant expiry=clock.instant().plusSeconds(600);synchronized(previews){previews.entrySet().removeIf(e->!e.getValue().expiresAt().isAfter(clock.instant()));if(previews.size()>=16)throw new LauncherApiException(503,"BUSY","安装计划已满，请先确认或稍后重试");previews.put(key,new Preview(id,plan,fabricPlan,loaderPlan,expiry));}var dto=new LinkedHashMap<String,Object>();dto.put("loader",plan.component()!=null?plan.component().kind().name():plan.fabricVersion()!=null?"FABRIC":"VANILLA");dto.put("loaderVersion",plan.component()!=null?plan.component().version():plan.fabricVersion());dto.put("fabricVersion",plan.fabricVersion());dto.put("planId",key.toString());dto.put("instanceId",id);dto.put("versionId",version);dto.put("platform",platform(plan.platform()));dto.put("requiredJavaMajor",plan.requiredJavaMajor());dto.put("fileCount",plan.files().size());dto.put("totalBytes",plan.totalBytes());dto.put("expiresAt",expiry.toString());return Optional.of(new ApiResponse(200,dto));});}
   if(r.path().equals("/installations/verify")){r.onlyFields(Set.of("instanceId"));String id=r.text("instanceId",36);version(id);return Optional.of(new ApiResponse(202,Map.of("task",TaskRoutes.view(tasks.submit(new TaskRequest(TaskKind.INSTALLATION_VERIFY,Map.of("instanceId",id)))))));}
   r.onlyFields(Set.of("planId"));UUID id;try{id=TaskRequest.uuid(r.text("planId",36));}catch(IllegalArgumentException invalid){throw ApiRequest.invalid("安装计划 ID 无效");}
   synchronized(previews){var preview=previews.get(id);if(preview==null||!preview.expiresAt().isAfter(clock.instant())){previews.remove(id);throw new LauncherApiException(410,"PLAN_EXPIRED","安装计划已使用或过期，请重新查看");}if(!version(preview.instanceId()).equals(preview.plan().versionId()))throw new LauncherApiException(409,"PLAN_CHANGED","实例版本已变化，请重新查看计划");var inputs=new HashMap<String,String>(Map.of("instanceId",preview.instanceId(),"versionId",preview.plan().versionId(),"metadataSha1",preview.plan().metadataSha1()));if(preview.fabricPlan()!=null){inputs.put("fabricVersion",preview.plan().fabricVersion());inputs.put("profileSha256",preview.fabricPlan().profileSha256());inputs.put("planSha256",preview.fabricPlan().fingerprint());}if(preview.loaderPlan()!=null){inputs.put("loader",preview.plan().component().kind().name());inputs.put("loaderVersion",preview.plan().component().version());inputs.put("sourceSha256",preview.loaderPlan().sourceSha256());inputs.put("planSha256",preview.loaderPlan().fingerprint());}var task=tasks.submit(new TaskRequest(preview.loaderPlan()!=null?TaskKind.LOADER_INSTALL:preview.fabricPlan()==null?TaskKind.VANILLA_INSTALL:TaskKind.FABRIC_INSTALL,inputs));previews.remove(id);return Optional.of(new ApiResponse(202,Map.of("task",TaskRoutes.view(task))));}
  }catch(TaskFailure error){throw TaskRoutes.failure(error);}
 }
 private LoaderProvider provider(String name){LoaderKind kind;try{kind=LoaderKind.valueOf(name);}catch(RuntimeException invalid){throw ApiRequest.invalid("加载器类型无效");}var provider=loaders.get(kind);if(provider==null)throw new IllegalArgumentException("此模式尚未接入所选加载器");return provider;}
 @Override public void close(){queries.close();}
 static Map<String,Object> platform(Platform p){return Map.of("osName",p.osName(),"osVersion",p.osVersion(),"arch",p.arch(),"bits",p.bits());}
 public static Map<String,Object> view(InstallationReceipt receipt){var m=new LinkedHashMap<String,Object>();m.put("fabricVersion",receipt.fabricVersion());m.put("loader",receipt.loaderKind().name());m.put("loaderVersion",receipt.loaderVersion());m.put("installationId",receipt.installationId());m.put("versionId",receipt.versionId());m.put("installedAt",receipt.installedAt().toString());m.put("fileCount",receipt.files().size());m.put("requiredJavaMajor",receipt.requiredJavaMajor());m.put("platform",platform(receipt.platform()));return m;}
}
